const body = $input.first().json.body || $input.first().json;
const quoteId = body.quote_id || body.id;

// Validate UUID or string presence
const isValid = Boolean(quoteId && typeof quoteId === 'string' && quoteId.trim().length > 0);

return [{
  json: {
    quote_id: quoteId ? quoteId.trim() : null,
    requested_by: body.requested_by || 'sales_agent',
    include_vat: body.include_vat !== undefined ? Boolean(body.include_vat) : true,
    is_valid_payload: isValid,
    received_at: new Date().toISOString()
  }
}];

