parameters.jsCode:
const item = $input.first().json;
let rawItems = item.items;

if (typeof rawItems === 'string') {
  try {
    rawItems = JSON.parse(rawItems);
  } catch (e) {
    rawItems = [];
  }
}
if (!Array.isArray(rawItems)) {
  rawItems = [];
}

let calculatedSubtotal = 0;
const normalizedItems = rawItems.map((p, idx) => {
  const qty = Number(p.quantity) || 1;
  const price = Number(p.unit_price) || 0;
  const lineTotal = qty * price;
  calculatedSubtotal += lineTotal;
  return {
    index: idx + 1,
    product: p.product || p.name || `Hạng mục ${idx + 1}`,
    quantity: qty,
    unit_price: price,
    total: lineTotal
  };
});

const discountPercent = Number(item.discount_percent) || 0;
const discountAmount = Math.round((calculatedSubtotal * discountPercent) / 100);
const totalAmount = calculatedSubtotal - discountAmount;

return [{
  json: {
    ...item,
    normalized_items: normalizedItems,
    calculated_subtotal: calculatedSubtotal,
    discount_amount: discountAmount,
    final_total: totalAmount,
    currency: 'VND',
    processed_at: new Date().toISOString()
  }
}];

const item = $input.first().json;

// Chuẩn bị metadata và buffer cho tệp PDF
const pdfMetadata = {
  quote_id: item.quote_id,
  file_name: `Bao_Gia_${item.quote_id.slice(0, 8).toUpperCase()}.pdf`,
  file_path: item.file_path,
  public_url: item.public_url,
  customer_name: item.customer_name,
  customer_email: item.customer_email,
  final_total: item.final_total,
  item_count: item.item_count,
  generated_at: new Date().toISOString(),
  status: 'GENERATED'
};

return [{
  json: pdfMetadata
}];

// Lấy trực tiếp dữ liệu báo giá chuẩn từ Node 10 trước khi chạy SQL UPDATE
const prevData = $('Code (PDF Engine Converter Metadata)').first().json;

const quoteId = prevData.quote_id || 'UNKNOWN';
const customerName = prevData.customer_name || 'Khách hàng';
const customerEmail = prevData.customer_email || 'N/A';
const finalTotal = prevData.final_total || 0;
const itemCount = prevData.item_count || 0;
const publicUrl = prevData.public_url || '#';

const totalFormatted = Number(finalTotal).toLocaleString('vi-VN');
const quoteShortId = quoteId.length >= 8 ? quoteId.slice(0, 8).toUpperCase() : quoteId;

const slackMessage = `📄 *BÁO GIÁ ĐÃ ĐƯỢC TẠO THÀNH CÔNG (WF-14)*\n` +
  `• *Khách hàng:* ${customerName} (${customerEmail})\n` +
  `• *Mã báo giá:* \`#${quoteShortId}\`\n` +
  `• *Số lượng hạng mục:* ${itemCount} dịch vụ\n` +
  `• *Tổng tiền:* *${totalFormatted} đ*\n` +
  `• *File PDF:* <${publicUrl}|Tải báo giá tại đây>\n` +
  `• *Thời gian:* ${new Date().toLocaleString('vi-VN')}`;

return [{
  json: {
    ...prevData,
    slack_message: slackMessage,
    notification_status: 'READY'
  }
}];

